    "abstractSummaryId": "The highest trends in employee turnover in companies are found in the Millennial generation. This trend is expected to continue to increase every year. This study aims to see how meaningful work influences the intention to leave the company through the role of work engagement as a mediator in the Millennial Generation sample. This research was conducted on 446 Millennial generation employees from various types of companies using convenience sampling methods. The instruments used in this study were Work as Meaning Inventory, Utrecht Work Engagement Scale-9, and Turnover Intention Scale. Based on mediation analy...",
