    "abstractSummaryId": "The recent Covid-19 pandemic has had significant psychological and social effects on the population. Research has highlighted the impact on psychological well-being of the most exposed groups, including children, college students, and health workers, who are more likely to develop post-traumatic stress disorder, anxiety, depression, and other symptoms of distress. The social distance and the security measures have affected the relationship among people and their perception of empathy toward others. From this perspective, telepsychology and technological devices assume important roles to decrease the negative e...",
