    "abstractSummaryId": "Even though studies on work-life balance and family-supportive supervisor behaviors are prevalent, there are few studies in the SME setting, and the implications are yet unexplained. Thus, the study examines the effect of work-life balance on the performance of employees in SMEs, along with the mediating role of job satisfaction and the moderating role of family-supportive supervisor behaviors. We have developed a conceptually mediated-moderated model for the nexus of work-life balance and job performance. We collected data from SMEs and employed SEM-PLS to test the research hypothesis and model. Empirical res...",
