    "abstractSummaryId": "This study investigated the impact of transformational leadership on affective organizational commitment and job performance with the mediating role of employee engagement. This study gathered data from 845 hotel employees in China and the structural equation modeling technique was used to verify the results. The findings indicated that transformational leadership has a positive effect on affective organizational commitment and job performance. Meanwhile, results showed that employee engagement partially mediates in the relationship between transformational leadership, affective organizational commitment, and...",
