    "keyFindings": [
      "Overall, and considering the scale range of each questionnaire, the results showed moderate values of operational stress, distress, and burnout.",
      "However, considering their cut-off points, 85% of the sample presented high operational stress levels, 11% critical values for burnout, and 28% high distress levels, with 55% of the sample at risk of a psychological disorder.",
      "These results reinforce the need to prevent stress and to invest in police officers' occupational health."
    ],
