    "abstractSummaryId": "The COVID-19 pandemic outbreak-as a typical emergency event-significantly has impacted employees' psychological status and thus has negatively affected their performance. Hence, along with focusing on the mechanisms and solutions to alleviate the impact of work stress on employee performance, we also examine the relationship between work stress, mental health, and employee performance. Furthermore, we analyzed the moderating role of servant leadership in the relationship between work stress and mental health, but the result was not significant. The results contribute to providing practical guidance for enterpr...",
