    "abstractSummaryId": "Numerous organizations have faced substantial environmental performance challenges resulting from more than a half-century of worldwide industrialization. Grounded in social learning theory and recourse-based view theory, this study explores environmental performance and its impact on employees and industry outcomes. Drawing on a cross-sectional online survey of 500 full-time employees working in the chemical industry in Lahore, Pakistan. The results revealed a significant positive influence of Green HRM practices on employees' Green innovation as well as on environmental performance. Additionally, significant...",
