      "Additionally, significant influences of study variables were recorded on outcomes such as green compensation and reward, green performance management and appraisal, green training and development, and green recruitment and selection.",
      "Several key policy insights related to consumer resistance to innovation in low income societies and future research directions are suggested, along with theoretical and practical implications."
