    "abstractSummaryId": "Perceptions of psychological empowerment play a vital role in the way an individual perceives things at the workplace. In spite of this, there is scant research on the antecedents and consequences of psychological empowerment. This study is an attempt to fill this gap by analyzing the mediating role of psychological empowerment on the relationship between its antecedents (leader-member exchange) and its consequences (work engagement and psychological withdrawal behavior). Data were collected from 454 employees working in the Research and Development (R&D) departments of the information technology (IT) and phar...",
