    "abstractSummaryId": "Although remote working can involve positive outcomes both for employees and organizations, in the case of the sudden and forced remote working situation that came into place during the COVID-19 crisis there have also been reports of negative aspects, one of which is technostress. In this context of crisis, leadership is crucial in sustainably managing and supporting employees, especially employees with workaholic tendencies who are more prone to developing negative work and health outcomes. However, while research on the role of the positive aspects of leadership during crises does exist, the negative aspects...",
