    "abstractSummaryId": "The radical changes deriving from the COVID-19 emergency have heavily upset some of the most familiar routines of daily work life. Abruptly, many workers have been forced to face the difficulties that come with switching to remote working. Basing on the theoretical framework proposed by the Job Demands-Resources model, the purpose of this paper was to explore the effect of work overload (workload and techno overload), on behavioral stress, meant as an outcome linked to the health impairment process. Furthermore, the aim of the study was to explore the mediating role of job crafting, considered as a second-orde...",
