    "abstractSummaryId": "This article examines the mechanisms that influence team-level performance. It investigates psychological safety, a shared belief that the team is safe for interpersonal risk taking and a causal model mediated by learning behavior and efficacy. This model hypothesizes that psychological safety and efficacy are related, which have been believed to be same-dimension constructs. It also explains the process of how learning behavior affects the team's efficacy. In a study of 104 field sales and service teams in South Korea, psychological safety did not directly affect team effectiveness. However, when mediated by...",
