    "abstractSummaryId": "Industry 4.0 has changed the paradigm in the business practice and business model, and digital technology has brought radical transformations to enterprises. To support this transformation, digital leaders are required to help enterprises transform and lead them to a more promising future. Based on job demands-resources model and person-organization fit theory, this study examines the relationship between digital leadership and employee creativity. Based on a sample of 357 employees from various Chinese companies, this study used SPSS 22.0 and MPLUS 7.0 to examine the hypotheses. The findings indicate the foll...",
