    "sampleContext": "Detail jumlah & karakteristik partisipan tercantum lengkap pada teks penuh artikel DOI",
    "keyFindings": [
      "(d) person-organization fit positively moderates the indirect effect of digital leadership on employee creativity via employee job crafting.",
      "The findings reveal the effect mechanism of digital leaders on employee creativity and enrich the literature on antecedents of employee creativity.",
      "Practical implications and future research are also discussed."
    ],
