    "abstractSummaryId": "During uncertain situations, such as the COVID-19 partial lockdown, maintaining satisfactory levels of employee performance (EP) is an important area of concern for many organizations. The current study examines the relationship of work stress due to COVID-19 (COVID-19 STR) and EP. Using social exchange theory (SET), safety culture (SC) is presented as a moderator for stress and performance relationships. A sample of 213 bank employees was collected using a convenient sampling method. Data were analyzed using stepwise linear regression and PROCESS Macro by Hayes (2013). Results revealed that COVID-19 STR has a...",
