    "abstractSummaryId": "Purpose of the Study: The significance of creativity and performance in the workplace has been illustrated on various occasions. This study aims to find out if there is a link between transformative leadership, organizational innovation, psychological issues such as hindrance and challenge stressors, and employee creativity and employee performance. There is still a lack of awareness of the factors that influence employee performance in small and medium businesses (SMEs) in Pakistan. Pakistan's SMEs have struggled to survive in their early years, with an initial failure rate of 90 percent to 95 percent. Method...",
