    "abstractSummaryId": "Authentic leadership has become increasingly important in the literature, attracting the attention of many scholars in the last decade. This study adopted an employee-centered perspective to guide its examination of the relationship between authentic leadership and individual performance and investigation of the sequential mediation of employees' affective commitment and individual creativity. An analysis was conducted of data collected from 214 employees working in different business sectors. The results reveal a statistically significant positive relationship between authentic leadership and employees' workp...",
