    "abstractSummaryId": "This paper aims at shedding light on the effects that intrinsic and extrinsic motivation, as predictors, have on heavy work investment of time and effort and on job engagement. Using a questionnaire survey, this study conducted a moderated-moderation analysis, considering two conditional effects-worker's status (working students vs. non-student employees) and country (Israel vs. Japan)-as potential moderators, since there are clear cultural differences between these countries. Data were gathered from 242 Israeli and 171 Japanese participants. The analyses revealed that worker's status moderates the effects of...",
