    "abstractSummaryId": "In recent years, many studies have been done to identify the factors that affect teacher emotions at schools. However, the empirical evidence on how teachers' emotions influence students' outcomes and performance is not extensive. Against this background, this study explored the correlation between teacher EI and student academic achievement and possible mechanisms may lie in this relationship. A sample of 365 Chinese teachers from 25 public middle schools participated in this study by completing measurements of teacher EI, teacher work engagement, and teacher self-efficacy. The student academic achievement wa...",
