    "abstractSummaryId": "Given the severity of today's environmental issues, companies are increasingly making green concepts a key component of their operational strategies. As an essential complement to corporate environmental strategy, employees' green behavior has received attention from all sectors of society. Based on resource conservation theory, this study explores the formation mechanism of employees' green behaviors in enterprises starting from two green management tools: green human resource management (HRM) practices and green transformational leadership. Through two-stage questionnaire research, 296 sample data points wer...",
