    "abstractSummaryId": "Social development organizations increasingly employ artificial intelligence (AI)-enabled tools to help team members collaborate effectively and efficiently. These tools are used in various team management tasks and activities. Based on the unified theory of acceptance and use of technology (UTAUT), this study explores various factors influencing employees' use of AI-enabled tools. The study extends the model in two ways: a) by evaluating the impact of these tools on the employees' collaboration and b) by exploring the moderating role of AI aversion. Data were collected through an online survey of employees wo...",
