    "sampleContext": "Detail jumlah & karakteristik partisipan tercantum lengkap pada teks penuh artikel DOI",
    "keyFindings": [
      "The results revealed that the antecedent variables, such as effort expectancy, performance expectancy, social influence, and facilitating conditions, are positively associated with using AI-enabled tools, which have a positive relationship with collaboration.",
      "It also concluded a significant effect of AI aversion in the relationship between performance expectancy and use of technology.",
      "These findings imply that organizations should focus on building an environment to adopt AI-enabled tools while also addressing employees' concerns about AI."
    ],
