    "abstractSummaryId": "This article reports on the development of an instrument to measure the perceived stress that results from the use and ubiquity of digital technology in the workplace. Based upon a contemporary understanding of stress and a set of stressors that is a substantial update to existing scales, the Digital Stressors Scale (DSS) advances the measurement of digital stress. Initially, 138 items were constructed for the instrument and grouped into a set of 15 digital stressors. Based on a sample of N = 1,998 online questionnaires completed by individuals representative of the US employed population, the scale was refine...",
