      "Through a nomological network that includes important outcome variables of digital stress (emotional exhaustion, innovation climate, job satisfaction, user satisfaction) it was then demonstrated that the DSS provides substantial explanatory power, particula...",
      "Thus, the DSS constitutes a state-of-the-art self-report instrument to measure the extent of distress appraisal related to digital technologies in the workplace and helps to explain further how and why information and communication technologies can lead to ..."
