    "abstractSummaryId": "Organizational management practices in promoting sustainable development of the ecological environment are becoming a crucial way for enterprises to gain competitive advantages. However, whether the goal of such practices can be achieved depends on employees' perception of environmental problems and the way they act. Therefore, it is important to stimulate employees' pro-environment behaviors through management activities. Building on affective events theory and self-determination theory, we examined the effect of environmentally specific transformational leadership on employees' pro-environmental behaviors (P...",
