    "abstractSummaryId": "Knowledge sharing between individuals is a key process for knowledge-intensive organizations to create value and gain a competitive edge. An individual is in the center of a complex set of factors, which are conducive to the knowledge-sharing process. The purpose of this empirical study is to explain the interaction mechanisms between personality and knowledge-sharing behavior and to examine the mediating effects of willingness to share knowledge and subjective norm. The theory of planned behavior, the social exchange theory, and the big five personality traits theory are combined to explain tacit knowledge-sh...",
