    "abstractSummaryId": "Background Effective teamwork and communication are imperative for patient safety and quality care. Communication errors and human failures are considered the main source of patient harm. Thus, team trainings focusing on communication and creating psychologically safe environments are required. This can facilitate challenging communication and teamwork scenarios, prevent patient safety risks, and increase team performance perception. The sparse research concerning communication interventions calls for an understanding of psychological mechanisms. Therefore, this study investigated mechanisms of an interpersona...",
