    "sampleContext": "Tercatat dalam abstrak artikel: N = 137 (lihat detail kriteria sampel pada artikel asli)",
    "keyFindings": [
      "Our results highlight the importance of teamwork for patient safety.",
      "Interpersonal and interprofessional team training represents a novel approach as it empirically brings together interpersonal communication and collaboration in the context of patient safety.",
      "Future research should work on follow-up measures in randomized-controlled trials to broaden an understanding of changes over time."
    ],
