    "abstractSummaryId": "Healthcare professionals who feel psychologically safe believe it is safe to take interpersonal risks such as voicing concerns, asking questions and giving feedback. Psychological safety is a complex phenomenon which is influenced by organizational, team and individual level factors. However, it has primarily been assessed as a team-level phenomenon. This study focused on understanding healthcare professionals' individual experiences of psychological safety. We aim to gain a fuller understanding of the influence team leaders, interpersonal relationships and individual characteristics have on individuals' psych...",
