    "keyFindings": [
      "The themes identified were: \"Personal Characteristics,\" \"Past Experiences,\" \"Individual Perceptions of Being Valued,\" and \"Judged Appropriateness of Issues/Concerns.\" These themes are explored within the context of motivating and inhibiting factors associat...",
      "These results extend existing theoretical frameworks guiding our understanding of psychological safety by accounting for the variation in individuals' experiences and studying these significant influences on voice behavior.",
      "Important considerations for the development of interventions to enhance psychological safety are discussed."
    ],
