    "abstractSummaryId": "The concept of work engagement (WE) has aroused the interest of many scholars. However, there has been limited academic research in examining how authentic leadership (AL) can influence WE, which consequently influences organizational citizenship behavior (OCB) and task performance (TP). In particular, this study divides WE into cognitive engagement, emotional engagement, and physical engagement to fully reflect the engagement theory. This study introduces three dimensions of WE and tests the theoretical model to validate cognitive engagement, emotional engagement, and physical engagement. Empirical testing us...",
