    "abstractSummaryId": "Although numerous studies have shown that prosocial behavior impacts performance within organizations, the mechanisms that encourage or discourage these effects have rarely been explored. Two studies were conducted to shed light on the role of psychological beliefs on prosocial dynamics in predicting organizational performance. In Study 1, employees' beliefs in their inner job-related resources (Occupational Efficacy - OE) were examined as a predictor of OCB. It was posited that OE, which is an inner resource, should positively predict OCB. Study 2 examined whether Collective Efficacy (CE), which is an externa...",
