    "sampleContext": "Detail jumlah & karakteristik partisipan tercantum lengkap pada teks penuh artikel DOI",
    "keyFindings": [
      "In Study 2, OCB positively predicted employee performance above and beyond and the effects of their managers' tenure in position, and CEs.",
      "In addition, both employees' and managers' CEs moderated the effects of OCB on performance: the performance effects of OCB increased as employees' and managers' CE increased, and specifically performance efficiency and performance creativity.",
      "These findings contribute to a better theoretical and practical understanding of the core factors that affect the organizational dynamics of prosocial behaviors that can lead to higher performance, and the ways in which OCB positively predicts performance i..."
    ],
