    "abstractSummaryId": "Online education has become a vital weapon to fight against the COVID-19 epidemic in the world. In the home-based online education environment, female pre-school teachers are expected to balance the dual roles of teacher and mother at the same time, which may trigger the work-family conflict. Although previous studies analyzed individual stressors, work-family conflict and its outcomes, there is little research on pre-school teachers' work and parenting experience during major public health emergencies. The current study examined the associations among work overload, parenting stress, work-family conflict, and...",
