    "abstractSummaryId": "Too many job demands and not enough job resources can negatively influence the well-being of employees. Currently, limited information exists surrounding the job demands and resources as experienced by academic employees in the higher education sector. Therefore, the aim of this study was to identify the job demands and job resources experienced by academic employees using qualitative methods. Semi-structured interviews were conducted with 23 academic employees, using an Interpretative Phenomenological Approach. Thematic analysis, specifically template analysis was used to categorize the themes. Job demands we...",
