    "abstractSummaryId": "Based on previous research, the conceptual model presenting the interaction between transformational leadership, challenge-hindrance stressors and thriving at work was constructed and used to generate the hypotheses for the study. Data were obtained from 542 questionnaires distributed across different organizations. The participants included ordinary employees, grassroots middle and senior managers from China. The major findings are as follows. First, transformational leadership directly is positively related to challenge stressors and thriving at work. Second, challenge stressors are positively relate to thri...",
