    "abstractSummaryId": "The employee organizational citizenship behavior for the environment (OCBE) contributes to the improvement of the organization's environment, its study is increasing in number. However, the psychological mechanism of promoting employee OCBE is still a missing link. Drawing on the theory of social information processing, this study seeks to establish the impact of green transformational leadership on employee OCBE and the mediating role of green organizational climate in this nexus. In addition, we have integrated environmental concerns to better explain the impact of this differentiation. The results show that...",
