    "sampleContext": "Tercatat dalam abstrak artikel: N = 270 (lihat detail kriteria sampel pada artikel asli)",
    "keyFindings": [
      "The subsequent longitudinal analysis confirmed the presumed directionality from purpose to engagement, but not to motivation.",
      "Hence, while a corporate purpose can be added to the list of antecedents to work engagement, the relationship with motivation, despite the significant association with purpose in the cross-sectional study, remains more complicated.",
      "The present study adds to the knowledge of the beneficial effects of a broader purpose and responds to the current surge of interest in purpose as an instrument for sustainable business."
    ],
