    "abstractSummaryId": "Objective: Based on the theory of perceived organizational support (POS), conservation of resource (COR) and job demands-resources (JD-R) model, this study establishes a moderated mediation model to test the role of job satisfaction in mediating the relationship between perceived organizational support and job burnout, as well as the role of regulatory emotional self-efficacy in moderating the above mediating process. Method: A total of 784 police officers were surveyed with the Perceived Organizational Support Scale, the Job Burnout Questionnaire, the Regulatory Emotional Self-Efficacy Scale, and the Minnesot...",
