    "abstractSummaryId": "This study is an investigation of the relationships among job meaningfulness, work engagement, and performance, including testing for a possible mediation effect of work engagement on the relationship between job meaningfulness and performance. We examine task interdependence as a boundary condition that facilitates employee engagement using two-stage multiple-source respondent data drawn from a sample of 183 Uzbek employees from public organizations and their 47 supervisors to test the hypotheses. The research findings confirm a positive association between job meaningfulness and engagement and the relationsh...",
