    "abstractSummaryId": "Background: In the rapidly evolving digital landscape, the role of middle managers in organizational structures and processes is increasingly pivotal. Positioned at the nexus of strategic directives and operational execution, they play an important role in driving digital transformation. This study discusses the under examined domain of middle managers' digital leadership and its impact on employee work engagement in the context of digital transformation. Design: Drawing on Social Exchange Theory, this study investigates the influence of middle managers' digital leadership on employee work engagement through t...",
