    "abstractSummaryId": "This study aims to examine the underlying mechanism of the relationship between perceived green human resource management (GHRM) and perceived employee green behavior (EGB). By drawing on attitude and social exchange theories, we examined green commitment (GC) as a mediator and green knowledge sharing (GKS) as a moderator of the GHRM–EGB relationship. The study employs partial least square structural equation modeling (PLS-SEM) to analyze 329 responses. Data were collected in two time lags. The empirical results confirmed that GC mediates the relationship between GHRM and EGB. However, the study results found...",
