    "keyFindings": [
      "This research signifies the effect of GHRM, GKS, GC, and green behavior on organizations’ sustainability and environmental management.",
      "Despite the emerging literature on the significance of green practices in organizations for environmental management, no study has examined the moderating role of GKS on the indirect effect of GHRM on green behavior via mediating role of GC.",
      "This study offers valuable insight into environmental management in organizations through green practices and green behavior."
    ],
