    "abstractSummaryId": "The impostor phenomenon (IP) refers to intense thoughts of fraudulence reported by high-achieving individuals. Since it has been shown to account for several personal and work-related complications, effective interventions are greatly needed. Against the background of mindset theory, we developed and tested two mindset interventions. We evaluated the impact of a coaching and a training intervention adopting a randomized controlled outcome design. One hundred and three young employees were randomly assigned to receive coaching (n = 36), training (n = 33), or no intervention (n = 34). Results reveal that coachin...",
