    "abstractSummaryId": "Introduction: Teaching is a stressful profession that exposes workers to the risk of burnout. Techniques involving higher mental functions, such as transcendental meditation and prayer, have been used in stress and burnout prevention programs. In this study, we report the results of an experience conducted in a group of teachers of a religious institute, in which prayer was used as a technique to prevent burnout. Methods: 50 teachers and support staff employed at a Catholic school of a Congregation of nuns volunteered for this study. They were randomized into 2 groups: Prayer Treatment (PT) (n = 25) or control...",
