    "sampleContext": "Tercatat dalam abstrak artikel: n = 25 (lihat detail kriteria sampel pada artikel asli)",
    "keyFindings": [
      "Emotional exhaustion (16.80 to 4.92, p < 0.001), Depersonalization (3.72 to 0.60, p <0.001) levels, psychological impairment (10.08 to 2.04, p< 0.001) were significantly decreased, job satisfaction (45.96 to 77.00, p< 0.001) was increased.",
      "The effect sizes (Glass’ Δ) of the therapeutic interventions ranged from 0.53 (satisfaction level) to 2.87 (psychological health), suggesting moderate to large effects.",
      "Discussion: Prayer could be effective, no less than meditation and other spiritual or mind-body techniques, in contrasting the negative effects of occupational stress and preventing burnout among teachers and, possibly, other human service professionals."
    ],
