    "abstractSummaryId": "Emotional exhaustion in the workplace can cause employees psychological and physical health problems, affect work performance, and create burdens for the organization. Existing studies have demonstrated that psychological empowerment helps reduce emotional exhaustion. This study explores the internal mechanism of this relationship. Drawing on conservation of resources theory, we advance a dual mediation model to explain how high psychological empowerment results in low emotional exhaustion, by increasing psychological safety and organizational embeddedness. Data were collected from 226 on-the-job MBA students...",
