    "abstractSummaryId": "For countries and organizations to achieve sustainable development, radical green creativity is required. Despite the fact that the influencing elements of green creativity have received a lot of attention, there is little research on the antecedents of green creativity. The current study attempted to fill the gap by exploring the underlying mechanism of green thinking and green organizational identity as mediators. This study aimed to examine the impact of green transformational leadership on green creativity through mediators, such as green thinking and creative organizational identity in SMEs. We gathered d...",
