    "abstractSummaryId": "What does it mean to be “strengths-based” or to be a “strengths-based practitioner?” These are diffuse areas that are generic and ill-defined. Part of the confusion arises from the customary default of practitioners and leaders across many cultures to label anything positive or complimentary as “strengths-based,” whether that be an approach, a theoretical orientation, an intervention, or a company. Additional muddle is created by many researchers and practitioners not making distinctions between very different categories of “strength” in human beings – strengths of character, of talent/ability, of interest/pas...",
