    "abstractSummaryId": "Emotional intelligence is extremely indispensable in functioning leadership positions as leaders wish everybody to fulfill his/her responsibilities and obligations effectively while job satisfaction has a direct association with the productivity and efficiency of an organization and also to individuals' success. Therefore, this cross-sectional study examined the relationship between emotional intelligence and job satisfaction among secondary schools heads in Khyber Pakhtunkhwa. For this investigation, a total of 402 out of 884 secondary school heads were taken as a sample using a multistage sampling technique....",
