    "abstractSummaryId": "Teachers' healthy and effective functioning at work is impacted by the demands they face and the resources they can access. In this study, person-centered analysis was adopted to identify distinct teacher profiles of demands and resources. We investigated teachers' experiences of two job demands (barriers to professional development and disruptive student behavior), two job resources (teacher collaboration and input in decision-making), and one personal resource (self-efficacy for teaching). Using data from the Teaching and Learning International Survey (TALIS) 2013, the study involved 6,411 teachers from 369...",
