    "abstractSummaryId": "BACKGROUND: The literature shows the negative psychological impact of the coronavirus disease 2019 (COVID-19) outbreak on frontline healthcare workers. However, few are known about the mental health of physicians and nurses working in general hospitals during the outbreak, caring for patients with COVID-19 or not. OBJECTIVES: This survey assessed differences in mental health in physicians and nurses working in COVID-19 or non-COVID-19 medical care units. DESIGN: A cross-sectional mixed-mode survey was used to assess burnout, insomnia, depression, anxiety, and stress. SETTING: A total of 1,244 physicians and nu...",
