    "abstractSummaryId": "Based on the social exchange theory, the aim of this study is to identify the association between job stress state anger, emotional exhaustion and job turnover intention. This study postulates that job related stress and state anger among nurses during COVID-19 subsequently leads to their job turnover intentions. In addition, the study also aims to see the mediating role of emotional exhaustion between COVID-19-related job stress, state anger, and turnover intentions. The sample of this study is gathered from 335 registered nurses working in Pakistani hospitals dealing with COVID-19-related patients. The inter...",
