    "abstractSummaryId": "Workplace ostracism, which is regarded as “social death,” is rampant in organizations and has attracted significant research attention. We extend the understanding of workplace ostracism by conducting a meta-analysis of studies of the relationships between workplace ostracism and its consequences. We also explore the moderating effects of national culture (i.e., collectivism vs. individualism) and the mediating effects of organization-based self-esteem (OBSE). The results of a meta-analysis of 95 independent samples ( N = 26,767) reveal that exposure to workplace ostracism is significantly related to individua...",
