    "abstractSummaryId": "Introduction: Teacher burnout and frequent turnover negatively affect stability and productivity in the context of higher education. Despite the fact that the relationship between burnout and turnover intention has been thoroughly studied, the role of other factors in this relationship should be evaluated in order to better clarify underlying mechanisms, particularly in the context of higher education. Methods: In this study, we first aim to bridge a research gap by utilizing job satisfaction as a mediating variable for the relationship between burnout and turnover intention. Moreover, we uniquely evaluate the...",
