    "abstractSummaryId": "Due to the higher attrition rate in higher education institutions (HEIs), the attraction and retention of top talents in higher education have become a challenge for human resource (HR) professionals. The primary area of discussion among business executives and HR professionals is how top talent can be retained and maintained. Thus, the purpose of this study is to examine the impact of human resource management practises (HRMPs), oraganisational reputation (OGR), occupational prestige (OPP) and work-life balance (WLB) on turnover intention (TOI) of the academics working in HEIs. The study also aims to examine...",
