    "abstractSummaryId": "Employee performance plays a crucial role in the productivity of organizations, especially in the hospitality industry in Malaysia. This work performance is influenced by leadership style, and finding the type of leadership style that is suitable to apply to employees is crucial, especially in the midst of the COVID-19 pandemic. Transformational leadership theory is selected for this study in determining leadership styles. There are four dimensions under transformational leadership theory, namely idealized influence, individualized consideration, inspirational motivation and intellectual stimulation. Data were...",
