    "abstractSummaryId": "The concept of workforce agility has become increasingly popular in recent years as agile individuals are expected to be better able to handle change and uncertainty. However, agility has rarely been studied in a systematic way. Relations between agility and positive work outcomes, such as higher performance or increased well-being, have often been suggested but rarely been empirically tested. Furthermore, several different workforce agility measures are used in the literature which complicates the comparison of findings. Recognizing these gaps in the literature, we developed a new workforce agility measure, c...",
