      "Creativity also mediated the relationship between perceived impact of COVID-19 and social well-being (social connectedness), but this connection was only found for the Chinese sample.",
      "Further data analyses revealed that individualism moderated this serial mediation model in that the positive coping effect of creativity on both flourishing and social well-being was stronger for individuals who hold more collectivistic views.",
      "Results of the study have implications for crisis management, personal development, and positive functioning of individuals and society."
