    "abstractSummaryId": "Background: Existing research indicates that job satisfaction has effects on job performance, but little evidence exists about the mechanism through which the satisfaction-performance association operates. This study aims to examine the effect of job satisfaction on job performance in a district-level health care system of China and to explore the effect mechanism mediated by organizational commitment and burnout. Methods: Cluster sampling was used in this study. All healthcare professionals in the Nanshan Medical Group, who were at work in the last 3 months and able to complete online questionnaire independen...",
