    "abstractSummaryId": "Mindfulness metacognitive practice that can be performed in the workplace. Drawing on the theory of conservation of resources, we test a moderated mediating model of how and when employee mindfulness has a positive effect on work engagement. Via analysis of data from 311 employees from 83 teams at different times, this study investigates the relationship between employee mindfulness and work engagement as well as the moderating effect of team mindfulness and the mediating effect of recovery level. The results from this multi-wave field study show that the mindfulness of the individual employee has a positive i...",
