    "abstractSummaryId": "Introduction: This study investigates the relationships between digital transformation (DT), challenging appraisal (CA), organizational culture support (OCS), transformational leadership style (TLS), and employee innovative behavior (EINB) in Brazzaville's banking sector. Grounded in Social Cognitive Theory and Self-Determination Theory, the research aims to provide insights into how these factors interact to influence innovation within organizations undergoing digital change. Methods: Data were collected from 280 employees working in the top five banks in Brazzaville. Structural Equation Modeling (SEM) was ap...",
