    "abstractSummaryId": "The COVID-19 outbreak has emphasized the importance of leadership style in achieving organizational performance. It also implies changes in administrative processes to remote working, impacting employee activities, and performance. Employee performance is one of the aspects that might influence a company's success. If employees are productive and provide high-quality work, the company's performance will increase. This study aims to analyze the effect of Transformational Leadership and Remote Working on Employee Performance during the COVID-19 pandemic. This study was conducted by performing a questionnaire dis...",
