    "abstractSummaryId": "This work explored the mediating effects of affective commitment on transformational leadership and job performance and job insecurity on transformational leadership and affective commitment. Meanwhile, the inter-relationships between the four verified the mediating effect of affective commitment, including job insecurity. The results were as follows: (1) transformational leadership and job performance were positively related. (2) Transformational leadership was proportional to an emotional commitment. (3) The affective commitment had a positive impact on job performance. (4) Transformational leadership indire...",
